ING_DELIVERY\",\"operational_session_creation\":\"DENY\",\"delivery_state_contract_rule_id\":505,\"provider_acceptance_is_delivery\":\"DENY\",\"webhook_required_before_verify_ui\":false,\"provider_acceptance_allows_verify_ui\":true,\"delivery_failure_account_existence_exposure\":\"DENY\"}. Los estados pendientes y restricciones de producción se conservan; binding runtime pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/493","solicitante":"Cristhian / Claude S22-AA 2026-11-25"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"s22aa06_evalua_otp_recuperacion"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"s22aa06_revela_elegibilidad"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s22aa06_otp_no_servidor_o_expuesto"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22aa06_scope_distinto_password_update"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22aa06_confunde_mfa_o_sesion"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22aa06_entrega_no_autoritativa"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22aa06_produccion_no_autorizada"},"der":{"lit":true}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s22aa06_evalua_otp_recuperacion":true,"s22aa06_revela_elegibilidad":false,"s22aa06_otp_no_servidor_o_expuesto":false,"s22aa06_scope_distinto_password_update":false,"s22aa06_confunde_mfa_o_sesion":false,"s22aa06_entrega_no_autoritativa":false,"s22aa06_produccion_no_autorizada":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s22aa06_evalua_otp_recuperacion":true,"s22aa06_revela_elegibilidad":true,"s22aa06_otp_no_servidor_o_expuesto":false,"s22aa06_scope_distinto_password_update":false,"s22aa06_confunde_mfa_o_sesion":false,"s22aa06_entrega_no_autoritativa":false,"s22aa06_produccion_no_autorizada":false},"esperado":true},{"casuistica":"SE_CUMPLE","entr